typedef unsigned int u_int;
struct nglMaterial {};
class nglVector { public: float x, y, z, w; } __attribute__((aligned(16)));

__asm__(".equ _$nglWaveHighlightAddr, 0x00001F40");
__asm__(".equ _$nglBaseAddr, 0x00000000");
__asm__(".equ SunPos, 0x005141A0");
__asm__(".equ HighlightAlphaScale, 0x0042E684");
__asm__(".equ HighlightAlphaOffset, 0x0042E688");
__asm__(".equ CoreHighlightAlphaScale, 0x0042E68C");
__asm__(".equ CoreHighlightAlphaOffset, 0x0042E690");
__asm__(".equ nglStageLightPass, 0x004AC9CE");
__asm__(".equ nglStageEnvironmentPass, 0x004AC9CD");
extern char nglWaveHighlightAddr asm("_$nglWaveHighlightAddr");
extern char nglBaseAddr asm("_$nglBaseAddr");
extern nglVector SunPos;
extern float HighlightAlphaScale, HighlightAlphaOffset;
extern float CoreHighlightAlphaScale, CoreHighlightAlphaOffset;
extern unsigned char nglStageLightPass, nglStageEnvironmentPass;
void nglFatal(const char *, ...);

#define SCE_VIF1_S_32 0x00
#define SCE_VIF1_V2_32 0x04
#define SCE_VIF1_V4_32 0x0c
#define SCE_VIF1_USN (1 << 14)
#define SCE_VIF1_SET_UNPACK(addr, qwc, mode, irq) (0x60000000 | ((mode) << 24) | ((qwc) << 16) | (addr))

inline void nglVif1AddCommandListProgram(u_int *&Packet, u_int &DataPtr, char *Addr)
{
  Packet[0] = SCE_VIF1_SET_UNPACK(DataPtr++, 1, SCE_VIF1_S_32, 0);
  Packet[1] = ((u_int)Addr - (u_int)&nglBaseAddr) / 8;
  Packet += 2;
}

inline void nglVif1AddCommandListData(u_int *&Packet, u_int &DataPtr, int Mode, int QWC, void *Data, int DataSize)
{
  u_int *DataWords = (u_int *)Data;
  *(Packet++) = SCE_VIF1_SET_UNPACK(DataPtr, QWC, Mode, 0) | SCE_VIF1_USN;
  do {
    *(Packet++) = *(DataWords++);
    DataSize -= 4;
  } while (DataSize);
  DataPtr += QWC;
}

void nglVif1AddWaveHighlight(u_int*& _Packet, u_int& _CmdListDataPtr, int asCore, nglMaterial* Material, u_int MaterialFlags, bool standalone )
{
	u_int* Packet = _Packet;
	u_int CmdListDataPtr = _CmdListDataPtr;

	if ( asCore == 0) // highlights
	{
		if ( !nglStageLightPass )
			return;

		nglVif1AddCommandListProgram(  Packet, CmdListDataPtr, &nglWaveHighlightAddr );
		nglVif1AddCommandListData( Packet, CmdListDataPtr, SCE_VIF1_V4_32, 1, &SunPos, sizeof(nglVector) );
		float ScaleOffset[] = {HighlightAlphaScale, HighlightAlphaOffset};
		nglVif1AddCommandListData( Packet, CmdListDataPtr, SCE_VIF1_V2_32, 1, (void *) ScaleOffset, sizeof(ScaleOffset) );
	}
	else if ( asCore == 1) // core specularity
	{
		if ( !nglStageEnvironmentPass )
			return;

		nglVif1AddCommandListProgram(  Packet, CmdListDataPtr, &nglWaveHighlightAddr );
		nglVif1AddCommandListData( Packet, CmdListDataPtr, SCE_VIF1_V4_32, 1, &SunPos, sizeof(nglVector) );
		float ScaleOffset[] = {CoreHighlightAlphaScale, CoreHighlightAlphaOffset};
		nglVif1AddCommandListData( Packet, CmdListDataPtr, SCE_VIF1_V2_32, 1, (void *) ScaleOffset, sizeof(ScaleOffset) );
	}
	else
	{
		nglFatal("Bad parameter\n");
	}

	_Packet = Packet;
	_CmdListDataPtr = CmdListDataPtr;
}
